mapper.select:
select  a.finishadflag, a.chooseorderflag, a.finishorderflag
from (adstatusofuser a )
where
    a.userunique=#{userUnique}
  and a.period=#{period}

select
    GROUPNAME,GROUPCREATERID,TEACHERID,USERNUMBERS,YEARS,PERIODSOFONEYEAR,CURRENTPERIOD,AUTOPERIODFRESH,AUTOYEARFRESH,ENABLEAUTOPERIODFRESH,ENABLEAUTOYEARFRESH
from gamegroup where GROUPNAME=#{groupName}

mapper.update:
update
    gamegroup set CURRENTPERIOD=#{currentPeriod} where
    GROUPNAME=#{groupName}

update gamegroupmember
set CURRENTPERIOD=CURRENTPERIOD + 1
where USERUNIQUE = #{userUnique};

update gamegroupmember
set CURRENTPERIOD = #{period}
where USERUNIQUE = #{userUnique}

mapper.select:
select min(CURRENTPERIOD)
from gamegroupmember
where GROUPNAME = #{groupName}
group by GROUPNAME;

select CURRENTPERIOD
from gamegroup
where GROUPNAME = #{groupName};

SELECT *
FROM gamegroup
WHERE GROUPNAME = #{gameName};

select *
from gamegroupmember
where GROUPNAME = #{gameGroup};

select USERNAME
from approveduser
where USERID = (select USERID from gamegroupmember where USERUNIQUE = #{userUnique});
